// Pure, private cart-identity oracle. No network, storage or monetary assertions.
// Missing/null artwork means no artwork; number/string IDs remain distinct.
const identity = require('./authenticated-session-contract.cjs');
function fail(code) {
  throw Object.assign(new Error(code), { code }); // Never interpolate private values.
}

function check(condition, code) {
  if (!condition) fail(code);
}

function validId(value) {
  return Number.isSafeInteger(value) ||
    (typeof value === 'string' && value.trim().length > 0);
}

function idKey(value) {
  return JSON.stringify([typeof value, value]);
}

function normalized(items) {
  check(Array.isArray(items), 'CHECKOUT_CART_ITEMS_REQUIRED');
  const ids = new Set();
  const rows = Array.from(items, item => {
    check(item && typeof item === 'object' && !Array.isArray(item), 'CHECKOUT_INVALID_CART_LINE');
    check(Object.hasOwn(item, 'id') && validId(item.id), 'CHECKOUT_INVALID_LINE_ID');
    check(!ids.has(idKey(item.id)), 'CHECKOUT_DUPLICATE_LINE_ID');
    ids.add(idKey(item.id));
    check(Object.hasOwn(item, 'product_slug') && typeof item.product_slug === 'string' &&
      item.product_slug.trim().length > 0, 'CHECKOUT_INVALID_PRODUCT_IDENTITY');
    check(Object.hasOwn(item, 'package_id') && validId(item.package_id), 'CHECKOUT_INVALID_PACKAGE_IDENTITY');
    const artwork = item.artwork_id ?? null;
    check(artwork === null || validId(artwork), 'CHECKOUT_INVALID_ARTWORK_IDENTITY');
    check(Object.hasOwn(item, 'quantity') && Number.isSafeInteger(item.quantity) && item.quantity > 0,
      'CHECKOUT_INVALID_CART_QUANTITY');
    return { id: item.id, product_slug: item.product_slug, package_id: item.package_id,
      artwork_id: artwork, quantity: item.quantity };
  });
  return rows.sort((a, b) => {
    const left = idKey(a.id), right = idKey(b.id);
    return left < right ? -1 : left > right ? 1 : 0;
  });
}

function checkedIntent(intent) {
  check(intent && typeof intent === 'object' && !Array.isArray(intent), 'CHECKOUT_INTENT_REQUIRED');
  check(typeof intent.slug === 'string' && intent.slug.trim().length > 0,
    'CHECKOUT_INVALID_INTENDED_PRODUCT');
  check(validId(intent.packageId), 'CHECKOUT_INVALID_INTENDED_PACKAGE');
  check(Number.isSafeInteger(intent.quantity) && intent.quantity > 0,
    'CHECKOUT_INVALID_INTENDED_QUANTITY');
}

function snapshot(items) {
  // This string contains private identities; callers must never persist/log it.
  return JSON.stringify(normalized(items));
}

function ownedLine(beforeItems, afterItems, intent) {
  checkedIntent(intent);
  const before = normalized(beforeItems), after = normalized(afterItems);
  // The whole product must be absent, including other packages/artworks. Do not
  // invent a merge contract or turn an existing user configuration into ours.
  check(before.every(item => item.product_slug !== intent.slug), 'CHECKOUT_PRODUCT_ALREADY_PRESENT');
  const original = new Map(before.map(item => [idKey(item.id), item]));
  const additions = after.filter(item => !original.has(idKey(item.id)));
  check(additions.length === 1, 'CHECKOUT_REQUIRES_ONE_NEW_LINE');
  check(after.length === before.length + 1, 'CHECKOUT_BASELINE_COMPOSITION_CHANGED');
  const remaining = after.filter(item => original.has(idKey(item.id)));
  check(JSON.stringify(remaining) === JSON.stringify(before), 'CHECKOUT_PREEXISTING_INTENT_CHANGED');
  const added = additions[0];
  check(added.product_slug === intent.slug && added.package_id === intent.packageId &&
    added.artwork_id === null, 'CHECKOUT_NEW_LINE_IDENTITY_MISMATCH');
  return added;
}

function identifyOwned(beforeItems, afterItems, intent) {
  // Composition ONLY. This delta does not prove who created the matching line.
  // New browser callers must establish provenance with the lifecycle below.
  // Quantity is intentionally checked separately so an attributed wrong-quantity
  // line can still be removed safely while the quantity assertion fails.
  return ownedLine(beforeItems, afterItems, intent).id;
}

function discoverOwned(beforeItems, afterItems, intent) {
  const added = ownedLine(beforeItems, afterItems, intent);
  check(added.quantity === intent.quantity, 'CHECKOUT_NEW_LINE_QUANTITY_MISMATCH');
  return added; // Private canonical row; never export it as public evidence.
}

function restored(beforeItems, afterItems) {
  try { return snapshot(beforeItems) === snapshot(afterItems); }
  catch { return false; } // Invalid data is never a successful restoration.
}

function successfulStatus(statusCode) {
  return Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300;
}

function createOwnershipLifecycle({ singleWriterConfirmed = false } = {}) {
  // Exclusivity is a real operational prerequisite supplied by the user for
  // this run interval; it is not inferred from closing windows or a cart delta.
  // There is no invented response correlation/lock in the observed contract.
  let intent, ownedId;
  const state = { armed: false, permitted: false, responseObserved: false,
    responseSucceeded: false, ownershipEstablished: false, removePermitted: false };
  function assertCleanupOwned(id) {
    check(state.ownershipEstablished && ownedId !== undefined &&
      idKey(id) === idKey(ownedId), 'CHECKOUT_CLEANUP_REQUIRES_ESTABLISHED_OWNERSHIP');
    return true;
  }

  return {
    arm(value) {
      check(singleWriterConfirmed === true, 'CHECKOUT_SINGLE_WRITER_REQUIRED');
      check(!state.armed, 'CHECKOUT_ADD_ALREADY_ARMED');
      checkedIntent(value);
      intent = { slug: value.slug, packageId: value.packageId, quantity: value.quantity };
      state.armed = true;
    },
    permitAdd(body) {
      check(singleWriterConfirmed === true && state.armed && !state.permitted,
        'CHECKOUT_ADD_NOT_ARMED_OR_ALREADY_PERMITTED');
      check(identity.exactKeys(body, ['product_slug', 'package_id', 'quantity']) &&
        body.product_slug === intent.slug && body.package_id === intent.packageId &&
        body.quantity === intent.quantity, 'CHECKOUT_PERMITTED_ADD_INTENT_MISMATCH');
      state.permitted = true;
    },
    observeAddResponse(statusCode) {
      check(state.permitted && !state.responseObserved, 'CHECKOUT_ADD_RESPONSE_WITHOUT_PERMITTED_REQUEST');
      check(Number.isInteger(statusCode) && statusCode >= 100 && statusCode <= 599,
        'CHECKOUT_ADD_RESPONSE_STATUS_INVALID');
      state.responseObserved = true;
      state.responseSucceeded = successfulStatus(statusCode);
      return state.responseSucceeded;
    },
    establish(beforeItems, afterItems) {
      check(singleWriterConfirmed === true && state.armed && state.permitted &&
        state.responseObserved && state.responseSucceeded && !state.ownershipEstablished,
      'CHECKOUT_OWNERSHIP_REQUIRES_SUCCESSFUL_PERMITTED_ADD');
      // This path is called only in the normal post-Add flow. Failure cleanup
      // must never discover/claim a new line after an uncertain Add outcome.
      ownedId = identifyOwned(beforeItems, afterItems, intent);
      state.ownershipEstablished = true;
      return ownedId;
    },
    assertCleanupOwned,
    permitRemove(id) {
      assertCleanupOwned(id);
      check(!state.removePermitted, 'CHECKOUT_OWNED_REMOVE_ALREADY_PERMITTED');
      state.removePermitted = true;
    },
    ownedId() { return ownedId; }, // Private memory only, never evidence.
    status() { return { ...state }; } // No private identifiers or intent.
  };
}

function assertRestored({ beforeItems, afterItems, ownedId, expectedMobile,
  expectedUserId, sessionUser, meUser, removeSucceeded, initialDrafts, finalDrafts } = {}) {
  // Both independent live reads must happen AFTER Remove in the browser flow.
  // This pure check challenges their contents, not the chronology of network IO.
  check(Number.isSafeInteger(expectedUserId) && expectedUserId > 0 &&
    identity.intendedOrdinaryUser(sessionUser, expectedMobile) &&
    sessionUser.id === expectedUserId, 'CHECKOUT_POST_REMOVE_SESSION_IDENTITY_MISMATCH');
  // Observed /me contract establishes mobile and role; no /me numeric id is
  // invented. Session supplies the independently anchored stable account id.
  check(identity.intendedMe(meUser, expectedMobile), 'CHECKOUT_POST_REMOVE_ME_IDENTITY_MISMATCH');
  check(removeSucceeded === true, 'CHECKOUT_RESTORATION_REQUIRES_SUCCESSFUL_REMOVE');
  check(validId(ownedId), 'CHECKOUT_RESTORATION_REQUIRES_OWNED_ID');
  const before = normalized(beforeItems), after = normalized(afterItems);
  check(before.every(item => idKey(item.id) !== idKey(ownedId)), 'CHECKOUT_OWNED_ID_PRESENT_IN_BASELINE');
  check(after.every(item => idKey(item.id) !== idKey(ownedId)), 'CHECKOUT_OWNED_LINE_REMAINS_AFTER_REMOVE');
  check(JSON.stringify(before) === JSON.stringify(after), 'CHECKOUT_UNRELATED_CART_CHANGED_AFTER_REMOVE');
  // Existing drafts are an explicit failed setup, never cleared or overwritten.
  // This run starts without either key, writes only its own synthetic draft,
  // and must return both keys to absent through the supported Remove flow.
  check(identity.exactKeys(initialDrafts, ['address', 'activeOrder']) &&
    initialDrafts.address === null && initialDrafts.activeOrder === null,
  'CHECKOUT_PREEXISTING_DRAFT_NOT_SUITE_OWNED');
  check(identity.exactKeys(finalDrafts, ['address', 'activeOrder']) &&
    finalDrafts.address === null && finalDrafts.activeOrder === null,
  'CHECKOUT_SUITE_DRAFT_REMAINS_AFTER_REMOVE');
  return true;
}

module.exports = { snapshot, identifyOwned, discoverOwned, restored,
  createOwnershipLifecycle, assertRestored };
